{
  "technical_and_design_decisions": [
    "Implement Capabilities Framework as per design doc: three capability maps (channel, application, orderer) with V1.1 capability; binaries crash if unsupported capability detected.",
    "Extend chaincode shim API with GetTrxState for read-your-writes during transaction simulation.",
    "Refactor MSPConfig to an interface to allow custom channel config block construction outside configtxgen.",
    "Remove chaincode singletons and replace with dependency injection to facilitate lifecycle work.",
    "Generate peer core.yaml and orderer.yaml from World config in test framework.",
    "Implement validation parameters interface for new chaincode lifecycle, including automatic majority endorsement policy for '+lifecycle' chaincode.",
    "Performance evaluation of CouchDB state database using benchmark scripts and existing tools.",
    "Produce video tutorial for adding organizations to a running network."
  ],
  "assumptions": [
    "Development team has strong familiarity with Hyperledger Fabric codebase and architecture.",
    "All necessary development environments and dependencies are already set up.",
    "No major unforeseen technical obstacles or scope changes beyond described user stories.",
    "Documentation and video production are considered part of the software increment effort.",
    "Performance testing leverages existing benchmark frameworks (e.g., caliper) and does not require building new tools from scratch.",
    "The Capabilities Framework implementation follows the linked design document and Gerrit examples closely.",
    "Chaincode singleton removal is limited to the codebase areas affecting lifecycle; other singletons may remain if not blocking.",
    "Test configuration generation uses existing World config structure without major changes to World config itself."
  ],
  "activities": [
    {
      "activity_id": "U1.1",
      "activity_name": "Design and specification review for Capabilities Framework",
      "activity_description": "Review design doc, Gerrit examples, and plan implementation details for capabilities maps, interfaces, and upgrade process.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U1.2",
      "activity_name": "Implement capabilities maps in channel configuration",
      "activity_description": "Add three capability maps (root channel, application, orderer) to channel config protobufs and configuration structures.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U1.3",
      "activity_name": "Define capabilities interfaces in api.go",
      "activity_description": "Modify fabric/common/channelconfig/api.go to define component-specific capability interfaces (e.g., OrdererCapabilities, ApplicationCapabilities, ChannelCapabilities) with methods like SetChannelModPolicyDuringCreate().",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U1.4",
      "activity_name": "Implement capability checks in orderer",
      "activity_description": "Integrate capability checks into orderer transaction filtering and channel creation logic; enforce orderer and channel capabilities.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U1.5",
      "activity_name": "Implement capability checks in peer",
      "activity_description": "Integrate capability checks into peer VSCC validation and commit phase; enforce peer and channel capabilities.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U1.6",
      "activity_name": "Implement crash behavior for unsupported capabilities",
      "activity_description": "Ensure binaries crash with clear error message when encountering unsupported capability in channel config.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U1.7",
      "activity_name": "Upgrade process validation and testing",
      "activity_description": "Test rolling upgrade scenario: upgrade all binaries, then enable capabilities via reconfiguration; verify orderers upgraded before enabling application capabilities.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U1.8",
      "activity_name": "Unit and integration tests for Capabilities Framework",
      "activity_description": "Write unit tests for capability interfaces and integration tests for mixed-version networks, capability enforcement, and crash behavior.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U1.9",
      "activity_name": "Documentation for Capabilities Framework",
      "activity_description": "Update developer and operator documentation with capabilities concept, configuration, and upgrade procedures.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U2.1",
      "activity_name": "Design GetTrxState API extension",
      "activity_description": "Define the new chaincode shim API method GetTrxState(key string) for read-your-writes during transaction.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U2.2",
      "activity_name": "Implement GetTrxState in chaincode shim",
      "activity_description": "Add GetTrxState implementation in shim layer to retrieve transient state written during current transaction.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U2.3",
      "activity_name": "Integrate with peer transaction simulation",
      "activity_description": "Modify peer transaction simulator to maintain transient writes and serve GetTrxState requests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U2.4",
      "activity_name": "Unit tests for GetTrxState",
      "activity_description": "Write unit tests for shim API and peer simulator integration.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U2.5",
      "activity_name": "Integration tests for RYW feature",
      "activity_description": "End-to-end tests with chaincode using GetTrxState to verify read-your-writes behavior.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U2.6",
      "activity_name": "Documentation for GetTrxState",
      "activity_description": "Document new API in chaincode developer guide.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U3.1",
      "activity_name": "Plan video content and script",
      "activity_description": "Create storyboard and script for video showing process of adding organizations to running network.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U3.2",
      "activity_name": "Record demonstration",
      "activity_description": "Record screen capture of step-by-step process including config updates, channel reconfiguration, and peer joining.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U3.3",
      "activity_name": "Edit and produce video",
      "activity_description": "Edit recordings, add annotations, diagrams, and narration; produce final video file.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U3.4",
      "activity_name": "Review and publish video",
      "activity_description": "Internal review, incorporate feedback, publish to documentation site or video platform.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U4.1",
      "activity_name": "Design performance test scenarios",
      "activity_description": "Define query workloads, data sizes, and metrics for CouchDB performance evaluation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U4.2",
      "activity_name": "Set up test environment with CouchDB",
      "activity_description": "Provision Fabric network with CouchDB as state database, configure monitoring.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U4.3",
      "activity_name": "Develop and run benchmark scripts",
      "activity_description": "Implement or adapt benchmark scripts (e.g., using Caliper) to execute query workloads and collect performance data.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U4.4",
      "activity_name": "Analyze results and produce report",
      "activity_description": "Analyze benchmark results, identify bottlenecks, and write performance report with recommendations.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U5.1",
      "activity_name": "Refactor MSPConfig to interface",
      "activity_description": "Change MSPConfig from concrete struct to interface to allow custom implementations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U5.2",
      "activity_name": "Implement custom config construction API",
      "activity_description": "Provide API for building channel config blocks programmatically without configtxgen.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U5.3",
      "activity_name": "Update configtxgen to use new interface",
      "activity_description": "Modify configtxgen tool to work with MSPConfig interface.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U5.4",
      "activity_name": "Tests for custom config construction",
      "activity_description": "Unit and integration tests for building channel configs via new API.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U5.5",
      "activity_name": "Documentation for custom config construction",
      "activity_description": "Document new API and usage examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U6.1",
      "activity_name": "Identify all chaincode singletons",
      "activity_description": "Audit codebase for chaincode-related singletons (e.g., chaincode registry, lifecycle managers).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U6.2",
      "activity_name": "Refactor to remove singletons",
      "activity_description": "Replace singletons with dependency injection or context-passing patterns.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "U6.3",
      "activity_name": "Update dependent code",
