      "most_likely_effort": 2
    },
    {
      "activity_id": "U7.2",
      "activity_name": "Implement generation for peer core.yaml",
      "activity_description": "Create template and generation logic for peer core.yaml from World config.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U7.3",
      "activity_name": "Implement generation for orderer.yaml",
      "activity_description": "Create template and generation logic for orderer.yaml from World config.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U7.4",
      "activity_name": "Integrate with test framework",
      "activity_description": "Hook generation into test setup so tests use generated configs.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U7.5",
      "activity_name": "Tests for config generation",
