      "activity_id": "U8.1",
      "activity_name": "Design validation parameters interface",
      "activity_description": "Define interface for returning validation parameters (endorsement policy, etc.) for a chaincode.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U8.2",
      "activity_name": "Implement interface for chaincode lifecycle",
      "activity_description": "Implement validation parameters retrieval for regular chaincodes in new lifecycle.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U8.3",
      "activity_name": "Special case for '+lifecycle' chaincode",
      "activity_description": "Implement automatic generation of signature policy requiring majority of orgs for '+lifecycle' chaincode.",
